-- Template properties & content audit (docs/36): refresh approved seeds.
-- Mirrors packages/shared/src/system-templates.ts for the templates changed in this pass.
-- New docs use TS seeds at composition time; this updates system template rows in DB
-- and seeds new A/B field keys onto workspaces that already adopted experiment_status.

update templates
set
  name = 'A/B Experiment',
  description = 'Hypothesis-driven experiment brief with ICE scoring, KPIs, variants, and decision',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Problem / Insight"}]},{"type":"paragraph","content":[{"type":"text","text":"Link the Problem or Insight document in Properties → Origin, then summarize the evidence that motivates this test.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[What did we learn or observe that justifies running this experiment?]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Problem Statement"}]},{"type":"paragraph","content":[{"type":"text","text":"State the business or user symptom — not the solution.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[e.g. Trial-to-paid conversion is flat despite traffic growth.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How Might We"}]},{"type":"paragraph","content":[{"type":"text","text":"Frame the opportunity as a How Might We question before locking the change.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[How might we …?]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hypothesis"}]},{"type":"paragraph","content":[{"type":"text","text":"If we [change], then [primary metric] will [direction], because [mechanism].","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If we "},{"type":"text","text":"[change]","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"[primary metric]","marks":[{"type":"bold"}]},{"type":"text","text":" will "},{"type":"text","text":"[increase/decrease]","marks":[{"type":"bold"}]},{"type":"text","text":", because "},{"type":"text","text":"[underlying reasoning].","marks":[{"type":"bold"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Rationale"}]},{"type":"paragraph","content":[{"type":"text","text":"Evidence, prior tests, or behavioral theory that supports the mechanism.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Why this change should move the metric.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Falsification"}]},{"type":"paragraph","content":[{"type":"text","text":"What result would prove the hypothesis wrong? Write this before you launch.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[We will reject the hypothesis if …]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Variants"}]},{"type":"paragraph","content":[{"type":"text","text":"Describe Control and Treatment. Add screenshots or mockups as images in this section.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Control — [current experience]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Variant — [what changes; attach image if helpful]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Results: Insight, Learning & Decision"}]},{"type":"paragraph","content":[{"type":"text","text":"After the run, record the outcome narrative here. Capture winner/loser/stopped and roll-out decision in Properties.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Insight:]"}]},{"type":"paragraph","content":[{"type":"text","text":"[Learning:]"}]},{"type":"paragraph","content":[{"type":"text","text":"[Decision:]"}]}]}'::jsonb,
  metadata = '{"document_type":"ab_experiment","use_cases":["A/B tests","Growth experiments","Feature rollout validation"],"supported_views":["kanban","dashboard","gantt"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"experiment_status","field_label":"Experiment status","field_type":"status","options":[{"value":"backlog","label":"Backlog","category":"unstarted"},{"value":"design","label":"Design","category":"unstarted"},{"value":"engineering","label":"Engineering","category":"started"},{"value":"live","label":"Live","category":"started"},{"value":"analyzing","label":"Analyzing","category":"started"},{"value":"concluded","label":"Concluded","category":"completed"}],"ai_fill_enabled":true},{"field_key":"launch_date","field_label":"Launch date","field_type":"date","ai_fill_enabled":true},{"field_key":"date_active","field_label":"Duration","field_type":"date_range","ai_fill_enabled":true},{"field_key":"target_sprint","field_label":"Target sprint/quarter","field_type":"text","ai_fill_enabled":false},{"field_key":"funnel_stage","field_label":"Funnel stage (AARRR)","field_type":"select","options":["acquisition","activation","retention","referral","revenue"],"ai_fill_enabled":true},{"field_key":"growth_loop","field_label":"Growth loop","field_type":"text","ai_fill_enabled":true},{"field_key":"psychological_layer","field_label":"Psychological layer","field_type":"text","ai_fill_enabled":true},{"field_key":"audience","field_label":"Audience","field_type":"text","ai_fill_enabled":true},{"field_key":"country","field_label":"Country","field_type":"text","ai_fill_enabled":true},{"field_key":"surface","field_label":"Surface","field_type":"text","ai_fill_enabled":true},{"field_key":"target_segment","field_label":"Target segment","field_type":"text","ai_fill_enabled":true},{"field_key":"impact","field_label":"Impact (1–10)","field_type":"number","ai_fill_enabled":false},{"field_key":"confidence","field_label":"Confidence (1–10)","field_type":"number","ai_fill_enabled":false},{"field_key":"ease","field_label":"Ease / effort (1–10)","field_type":"number","ai_fill_enabled":false},{"field_key":"cost_of_experimentation","field_label":"Cost of experimentation","field_type":"number","options":{"unit":"days"},"ai_fill_enabled":false},{"field_key":"primary_kpi_label","field_label":"Primary KPI label","field_type":"text","ai_fill_enabled":true},{"field_key":"primary_kpi_baseline","field_label":"Primary KPI baseline","field_type":"text","ai_fill_enabled":true},{"field_key":"primary_kpi_target","field_label":"Primary KPI target","field_type":"text","ai_fill_enabled":true},{"field_key":"secondary_kpi_label","field_label":"Secondary KPI label","field_type":"text","ai_fill_enabled":true},{"field_key":"secondary_kpi_baseline","field_label":"Secondary KPI baseline","field_type":"text","ai_fill_enabled":true},{"field_key":"secondary_kpi_target","field_label":"Secondary KPI target","field_type":"text","ai_fill_enabled":true},{"field_key":"guardrail_kpi_label","field_label":"Guardrail KPI label","field_type":"text","ai_fill_enabled":true},{"field_key":"guardrail_kpi_baseline","field_label":"Guardrail KPI baseline","field_type":"text","ai_fill_enabled":true},{"field_key":"guardrail_kpi_target","field_label":"Guardrail KPI target","field_type":"text","ai_fill_enabled":true},{"field_key":"experiment_result","field_label":"Result","field_type":"select","options":["winner","loser","stopped","inconclusive"],"ai_fill_enabled":false},{"field_key":"experiment_decision","field_label":"Decision","field_type":"select","options":["roll_out","do_nothing","iterate"],"ai_fill_enabled":false},{"field_key":"primary_kpi_result_label","field_label":"Primary KPI result label","field_type":"text","ai_fill_enabled":false},{"field_key":"primary_kpi_result_value","field_label":"Primary KPI result value","field_type":"text","ai_fill_enabled":false},{"field_key":"secondary_kpi_result_label","field_label":"Secondary KPI result label","field_type":"text","ai_fill_enabled":false},{"field_key":"secondary_kpi_result_value","field_label":"Secondary KPI result value","field_type":"text","ai_fill_enabled":false},{"field_key":"erosion_risk","field_label":"Long-term erosion tracking","field_type":"checkbox","ai_fill_enabled":false}],"default_properties":{"status":"draft","experiment_status":"backlog","funnel_stage":"activation"}}'::jsonb
where slug = 'ab-experiment'
  and coalesce(is_system, false) = true
  and workspace_id is null;

update templates
