  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Core Insight"}]},{"type":"paragraph","content":[{"type":"text","text":"State the insight in one or two sentences. Link related Problem or Experiment docs via Properties → Origin when useful.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[The insight, stated plainly.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"User Quotes / Data Evidence"}]},{"type":"paragraph","content":[{"type":"text","text":"The evidence that backs this up — quotes, numbers, or links to sources.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Quote or data point 1]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Quote or data point 2]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Recommended Action"}]},{"type":"paragraph","content":[{"type":"text","text":"What should happen next — an idea to validate, or an experiment to design.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Proposed next step.]"}]}]}'::jsonb,
