update templates
set
  name = 'Product Spec',
  description = 'Problem, hypothesis, scope, UX flow, and success metrics',
  structure_json = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Problem & Insight"}]},{"type":"paragraph","content":[{"type":"text","text":"What problem are we solving, and what evidence validates it? Link related Insight or Problem docs via Properties → Origin.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"[Describe the core problem and the user insight or data that validates it.]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hypothesis"}]},{"type":"paragraph","content":[{"type":"text","text":"If / then / because — keep it falsifiable.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If we "},{"type":"text","text":"[build/change this feature]","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"[this behavior will happen]","marks":[{"type":"bold"}]},{"type":"text","text":", because "},{"type":"text","text":"[underlying reasoning].","marks":[{"type":"bold"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Goals & Non-Goals"}]},{"type":"paragraph","content":[{"type":"text","text":"Be explicit about what is out of scope to prevent creep.","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"type":"text","text":"In Scope:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Key deliverable 1]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Key deliverable 2]"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Out of Scope:","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[What we are NOT building right now]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"User Experience & Flow"}]},{"type":"paragraph","content":[{"type":"text","text":"Walk through the journey in order.","marks":[{"type":"italic"}]}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Step 1 of the user journey]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Step 2 of the user journey]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Technical Architecture & Considerations"}]},{"type":"paragraph","content":[{"type":"text","text":"Data, APIs, and constraints that affect the build.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Data structure changes, API requirements, or frontend/backend constraints]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Success Metrics"}]},{"type":"paragraph","content":[{"type":"text","text":"One primary metric and one guardrail that must not degrade.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Primary Metric: [What determines success?]"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Guardrail Metric: [What should not degrade?]"}]}]}]}]}'::jsonb,
  metadata = '{"document_type":"product_spec","use_cases":["Feature specs","Quarterly planning","PRD drafts","Experiment design"],"supported_views":["kanban","gantt","dashboard"],"schema_fields":[{"field_key":"status","field_label":"Status","field_type":"select","options":["draft","in_progress","done"],"ai_fill_enabled":true},{"field_key":"due_date","field_label":"Due","field_type":"date","ai_fill_enabled":true},{"field_key":"owner","field_label":"Owner","field_type":"text","ai_fill_enabled":true},{"field_key":"summary","field_label":"Summary","field_type":"textarea","ai_fill_enabled":true},{"field_key":"origin","field_label":"Origin","field_type":"relation","ai_fill_enabled":false},{"field_key":"priority","field_label":"Priority","field_type":"select","options":["p0","p1","p2","p3"],"ai_fill_enabled":true},{"field_key":"milestone","field_label":"Milestone","field_type":"text","ai_fill_enabled":true}],"default_properties":{"status":"draft","priority":"p2"}}'::jsonb
