Requirement description]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Must"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[S/M/L]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Not started]"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"REQ-2"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Requirement description]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Should"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[S/M/L]"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"[Not started]"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Out of Scope"}]},{"type":"paragraph","content":[{"type":"text","text":"What this explicitly does not cover — prevents scope creep.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Out of scope item]"}]}]}]}]}'::jsonb,
