-- Seed new A/B Experiment fields onto workspaces that already use experiment_status.
insert into metadata_schemas (workspace_id, field_key, field_label, field_type, options, ai_fill_enabled)
select
  ms.workspace_id,
  v.field_key,
  v.field_label,
  v.field_type,
  v.options,
  v.ai_fill_enabled
from (
  select distinct workspace_id
  from metadata_schemas
  where field_key = 'experiment_status'
) ms
cross join (
  values
    ('launch_date', 'Launch date', 'date', null::jsonb, true),
    ('growth_loop', 'Growth loop', 'text', null::jsonb, true),
    ('psychological_layer', 'Psychological layer', 'text', null::jsonb, true),
    ('audience', 'Audience', 'text', null::jsonb, true),
    ('country', 'Country', 'text', null::jsonb, true),
    ('surface', 'Surface', 'text', null::jsonb, true),
    ('primary_kpi_label', 'Primary KPI label', 'text', null::jsonb, true),
    ('primary_kpi_baseline', 'Primary KPI baseline', 'text', null::jsonb, true),
    ('primary_kpi_target', 'Primary KPI target', 'text', null::jsonb, true),
    ('secondary_kpi_label', 'Secondary KPI label', 'text', null::jsonb, true),
    ('secondary_kpi_baseline', 'Secondary KPI baseline', 'text', null::jsonb, true),
    ('secondary_kpi_target', 'Secondary KPI target', 'text', null::jsonb, true),
    ('guardrail_kpi_label', 'Guardrail KPI label', 'text', null::jsonb, true),
    ('guardrail_kpi_baseline', 'Guardrail KPI baseline', 'text', null::jsonb, true),
    ('guardrail_kpi_target', 'Guardrail KPI target', 'text', null::jsonb, true),
    ('experiment_result', 'Result', 'select', '["winner","loser","stopped","inconclusive"]'::jsonb, false),
    ('experiment_decision', 'Decision', 'select', '["roll_out","do_nothing","iterate"]'::jsonb, false),
    ('primary_kpi_result_label', 'Primary KPI result label', 'text', null::jsonb, false),
    ('primary_kpi_result_value', 'Primary KPI result value', 'text', null::jsonb, false),
    ('secondary_kpi_result_label', 'Secondary KPI result label', 'text', null::jsonb, false),
    ('secondary_kpi_result_value', 'Secondary KPI result value', 'text', null::jsonb, false)
) as v(field_key, field_label, field_type, options, ai_fill_enabled)
where not exists (
  select 1
  from metadata_schemas existing
  where existing.workspace_id = ms.workspace_id
    and existing.field_key = v.field_key
);

-- Rename date_active label to Duration on existing workspaces (A/B timeline).
update metadata_schemas
set field_label = 'Duration'
where field_key = 'date_active'
  and field_label = 'Timeline';
